    """Extend colored markers along their directional tracks; crossings spawn a 4 diagonal."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    tracks = []  # (color, list of cells along the marker's path, endpoint)
    directions = {
        2: (0, -1, 4),
