            color = grid[r][c]
            if color in directions:
                dr, dc, length = directions[color]
                cells = [(r + dr * k, c + dc * k) for k in range(length + 1)]
                tracks.append((color, cells, cells[-1]))
            elif color == 1:
                # Color 1 makes a two-cell eastward stroke, then ends one row up.
                cells = [(r, c), (r, c + 1), (r, c + 2)]
                endpoint = (r - 1, c + 2)
                tracks.append((color, cells, endpoint))

    # Paint strokes and their terminal markers, clipping only at grid boundaries.
    for color, cells, endpoint in tracks:
        for p, (r, c) in enumerate(cells):
            if 0 <= r < h and 0 <= c < w:
