                if (r, c) == endpoint:
                    out[r][c] = color
                elif grid[r][c] == 0:
                    out[r][c] = 5
        er, ec = endpoint
        if 0 <= er < h and 0 <= ec < w:
            out[er][ec] = color

    # A shared track cell is a crossing; mark it 4 and project a southwest diagonal.
    coverage = {}
    for _, cells, _ in tracks:
        for r, c in cells[1:]:
            if 0 <= r < h and 0 <= c < w:
                coverage[(r, c)] = coverage.get((r, c), 0) + 1
    crossings = [p for p, count in coverage.items() if count > 1]
    for r, c in crossings:
